INSERT INTO `comments` VALUES
(1, 6, 1, '2008-09-20 19:01:32', 'Залил и свалил. Анти-респект', 'Залил и свалил. Анти-респект', 0, '0000-00-00 00:00:00', '0', '0', '151.80.142.24'),
(2, 6, 5, '2008-09-23 00:52:26', 'интересно а у когонибуть есть японская музыка?', 'интересно а у когонибуть есть японская музыка?', 0, '0000-00-00 00:00:00', '0', '0', '151.80.96.38'),
(12, 1, 27, '2008-10-04 22:48:44', '[family=Verdana][b][color=red]Надо будет посмотреть[/color][/b][/family]', '[family=Verdana][b][color=red]Надо будет посмотреть[/color][/b][/family]', 0, '0000-00-00 00:00:00', '0', '0', '77.41.6.38'),
(21, 11, 75, '2008-10-21 14:44:29', 'Спасибо за раздачу и за золото!', 'Спасибо за раздачу и за золото!', 0, '0000-00-00 00:00:00', '0', '0', '77.41.49.195'),
(22, 71, 80, '2008-10-22 16:13:43', '[color=red][b]Призыв качать именно ваши (вашу) раздачу в комментариях, на форуме, в подписях, и чате строго запрещено.[/b][/color]', '[color=green][b] -Качать всем[/b][/color]', 1, '2008-10-22 21:58:28', '0', '0', '77.87.156.28'),
(10, 4, 27, '2008-10-03 22:50:31', 'как фильм?', 'как фильм?', 0, '0000-00-00 00:00:00', '0', '0', '79.165.170.141'),
(11, 11, 27, '2008-10-04 00:33:19', 'Нормальный, но больше похож на мелодрамму...', 'Нормальный, но больше похож на мелодрамму...', 0, '0000-00-00 00:00:00', '0', '0', '79.164.33.41'),
(9, 11, 18, '2008-09-30 13:36:44', 'Ты хоть оформи...', 'Ты хоть оформи...', 0, '0000-00-00 00:00:00', '0', '0', '79.164.43.149'),
(14, 6, 15, '2008-10-06 17:18:01', 'need more speed.', 'need more speed.', 0, '0000-00-00 00:00:00', '0', '0', '151.80.23.212'),
(15, 1, 30, '2008-10-08 22:07:30', '[family=Verdana][b][color=red]Вот это вещь, спасибо большое Тинхаер.[/color][/b][/family]', '[family=Verdana][b][color=red]Вот это вещь, спасибо большое Тинхаер.[/color][/b][/family]', 0, '0000-00-00 00:00:00', '0', '0', '77.41.9.121'),
(16, 11, 30, '2008-10-08 22:39:56', 'Ага, на здоровье, фильм офигенский.', 'Ага, на здоровье, фильм офигенский.', 0, '0000-00-00 00:00:00', '0', '0', '77.41.49.32'),
(17, 11, 32, '2008-10-09 09:36:51', 'Классный фильм! Спасибо', 'Классный фильм! Спасибо', 0, '0000-00-00 00:00:00', '0', '0', '77.41.49.32'),
(41, 1, 96, '2008-11-03 22:26:18', 'Steam нужен ?', 'Steam нужен ?', 0, '0000-00-00 00:00:00', '0', '0', '77.41.2.196'),
